[{"order":1,"type":"heading","text":"Configuring View Engines (EJS, Pug, Handlebars) in Express.js"},{"order":2,"type":"paragraph","text":"View engines allow you to render dynamic HTML pages on the server side using template files. Instead of sending static HTML, you can pass data from your Express.js routes directly into these templates, which are then compiled into standard HTML and sent to the client."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"Before configuring a view engine, ensure you have Node.js and Express installed in your project. You will also need to install the specific view engine package you wish to use."},{"order":5,"type":"code","text":"npm install express"},{"order":6,"type":"subheading","text":"1. Configuring EJS (Embedded JavaScript)"},{"order":7,"type":"paragraph","text":"EJS is a simple templating language that lets you generate HTML markup with plain JavaScript. First, install the EJS package."},{"order":8,"type":"code","text":"npm install ejs"},{"order":9,"type":"paragraph","text":"Next, configure Express to use EJS as the default view engine. By default, Express looks for view files inside a directory named "views" in the root directory."},{"order":10,"type":"code","text":"const express = require('express');
const app = express();

app.set('view engine', 'ejs');

app.get('/', (req, res) => {
  res.render('index', { title: 'Welcome to EJS' });
});

app.listen(3000);"},{"order":11,"type":"subheading","text":"2. Configuring Pug (Formerly Jade)"},{"order":12,"type":"paragraph","text":"Pug is a high-performance template engine heavily influenced by Haml, implementing indentation-based syntax. Install the Pug package to get started."},{"order":13,"type":"code","text":"npm install pug"},{"order":14,"type":"paragraph","text":"Configure Pug in your Express application similarly by setting the view engine property to "pug"."},{"order":15,"type":"code","text":"const express = require('express');
const app = express();

app.set('view engine', 'pug');

app.get('/', (req, res) => {
  res.render('index', { title: 'Welcome to Pug' });
});

app.listen(3000);"},{"order":16,"type":"subheading","text":"3. Configuring Handlebars (hbs)"},{"order":17,"type":"paragraph","text":"Handlebars is a semantic template engine that uses mustache-like syntax to ensure your templates remain free of logic. For Express, the "hbs" package is commonly used."},{"order":18,"type":"code","text":"npm install hbs"},{"order":19,"type":"paragraph","text":"Configure Handlebars in your Express application."},{"order":20,"type":"code","text":"const express = require('express');
const app = express();

app.set('view engine', 'hbs');

app.get('/', (req, res) => {
  res.render('index', { title: 'Welcome to Handlebars' });
});

app.listen(3000);"},{"order":21,"type":"subheading","text":"Customizing the Views Directory"},{"order":22,"type":"paragraph","text":"If you prefer to store your template files in a folder other than the default "views" directory, you can explicitly configure the path using app.set('views', ...)."},{"order":23,"type":"code","text":"const path = require('path');

// Custom views directory setup
app.set('views', path.join(__dirname, 'templates'));
app.set('view engine', 'ejs');"},{"order":24,"type":"subheading","text":"Best Practices"},{"order":25,"type":"bullet_point","text":"Always organize your template files into logical subfolders (e.g., layouts,partials, pages) for better maintainability."},{"order":26,"type":"bullet_point","text":"Use layouts or partials to avoid repeating common HTML structure like headers and footers across multiple views."},{"order":27,"type":"bullet_point","text":"Sanitize user input before passing it to view engines to prevent Cross-Site Scripting (XSS) vulnerabilities, noting that engines like Handlebars escape output by default."}]
